1: using System;
2: using System.IO;
3: using System.Windows;
4: 
5: namespace D2RBot.GUI
6: {
7:     public partial class App : Application
8:     {
9:         private static string LogFilePath = Path.Combine(Path.GetTempPath(), "D2RBot_GUI_Error.log");
10: 
11:         public App()
12:         {
13:             LogToFile("App constructor called");
14:             try
15:             {
16:                 AppDomain.CurrentDomain.UnhandledException += CurrentDomain_UnhandledException;
17:                 DispatcherUnhandledException += App_DispatcherUnhandledException;
18:                 LogToFile("Exception handlers registered");
19:             }
20:             catch (Exception ex)
21:             {
22:                 LogToFile($"Error in App constructor: {ex.Message}\n{ex.StackTrace}");
23:                 throw;
24:             }
25:         }
26: 
27:         private void CurrentDomain_UnhandledException(object sender, UnhandledExceptionEventArgs e)
28:         {
29:             Exception ex = (Exception)e.ExceptionObject;
30:             string msg = $"Unhandled Exception:\n\n{ex.Message}\n\n{ex.StackTrace}";
31:             LogToFile(msg);
32:             MessageBox.Show(msg, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
33:         }
34: 
35:         private void App_DispatcherUnhandledException(object sender, System.Windows.Threading.DispatcherUnhandledExceptionEventArgs e)
36:         {
37:             string msg = $"Dispatcher Unhandled Exception:\n\n{e.Exception.Message}\n\n{e.Exception.StackTrace}";
38:             LogToFile(msg);
39:             MessageBox.Show(msg, "Error", MessageBoxButton.OK, MessageBoxImage.Error);
40:             e.Handled = true;
41:         }
42: 
43:         private static void LogToFile(string message)
44:         {
45:             try
46:             {
47:                 File.AppendAllText(LogFilePath, $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss.fff}] {message}\n");
48:             }
49:             catch { }
50:         }
51:     }
52: }

