{
    PROCESSENTRY32 pe32;
    pe32.dwSize = sizeof(PROCESSENTRY32);

    HANDLE hProcessSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (hProcessSnap == INVALID_HANDLE_VALUE)
        return false;

    // Look for Diablo II: Resurrected
    if (Process32First(hProcessSnap, &pe32))
    {
        do
        {
            if (_stricmp(pe32.szExeFile, "d2r.exe") == 0)
            {
                m_processId = pe32.th32ProcessID;
                CloseHandle(hProcessSnap);
                return true;
            }
        } while (Process32Next(hProcessSnap, &pe32));
    }

    CloseHandle(hProcessSnap);
    return false;
}

bool BotEngine::AttachToProcess(DWORD processId)
{
    m_processHandle = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, processId);
    if (m_processHandle == nullptr)
        return false;

    // Get the base address of d2r.exe module
    HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, processId);
    if (hModuleSnap != INVALID_HANDLE_VALUE)
    {
        MODULEENTRY32 me32;
        me32.dwSize = sizeof(MODULEENTRY32);

        if (Module32First(hModuleSnap, &me32))
        {
            do
            {
                if (_stricmp(me32.szModule, "d2r.exe") == 0)
                {
                    m_gameModule = me32.hModule;
                    m_baseAddress = me32.modBaseAddr;
                    CloseHandle(hModuleSnap);
                    return true;
                }
            } while (Module32Next(hModuleSnap, &me32));
        }

        CloseHandle(hModuleSnap);
    }

    return m_baseAddress != nullptr;
}

