bool BotEngine::Start(const char* route)
{
    if (!m_isInitialized)
        return false;

    m_isRunning = true;

    // Find D2R window to send input to
    HWND hGameWindow = FindWindowA(nullptr, "Diablo II: Resurrected");
    if (!hGameWindow)
        hGameWindow = FindWindowA(nullptr, "D2R");
    if (!hGameWindow)
        hGameWindow = GetForegroundWindow();  // Fallback to active window

    // Send click commands to move character around
    if (hGameWindow && m_processHandle)
    {
        // Bring game window to front
        SetForegroundWindow(hGameWindow);
        Sleep(100);

        // Perform test movement pattern - right-click at different positions
        // This simulates clicking around the map to move the character
        int clicks[] = {
            100, 100,  // Top-left area
            200, 150,  // Right area
            150, 250,  // Bottom area
            100, 200,  // Back to center area
        };

        // Send mouse clicks (max 4 clicks per run)
        for (int i = 0; i < 4; i++)
        {
            if (!m_isRunning) break;

            int x = clicks[i * 2];
            int y = clicks[i * 2 + 1];

            // Right-click at position (in-game coordinate mapping)
            SetCursorPos(500 + x, 300 + y);  // Offset to game window center
            Sleep(50);
            mouse_event(MOUSEEVENTF_RIGHTDOWN, 0, 0, 0, 0);
            Sleep(50);
            mouse_event(MOUSEEVENTF_RIGHTUP, 0, 0, 0, 0);
            Sleep(200);  // Wait for move to complete
        }
    }

    return true;
}

