void BotEngine::ExecuteRoute(const char* route)
{
    // Find D2R window to send input to
    HWND hGameWindow = FindWindowA(nullptr, "Diablo II: Resurrected");
    if (!hGameWindow)
        hGameWindow = FindWindowA(nullptr, "D2R");
    if (!hGameWindow)
        hGameWindow = GetForegroundWindow();

    if (!hGameWindow || !m_processHandle)
        return;

    SetForegroundWindow(hGameWindow);
    Sleep(200);

    // Route waypoint coordinates (screen positions for clicking)
    struct Waypoint { int x; int y; const char* name; };

    // Cow Level - areas to clear
    Waypoint cowLevelRoute[] = {
        { 640, 360, "Center" },
        { 680, 350, "E" },
        { 720, 360, "NE" },
        { 700, 380, "SE" },
        { 640, 400, "S" },
        { 580, 380, "SW" },
        { 560, 360, "W" },
        { 580, 340, "NW" },
        { 640, 360, "Center2" },
    };

    // Pit - entrance and chamber
    Waypoint pitRoute[] = {
        { 640, 360, "Start" },
        { 650, 350, "Enter" },
        { 670, 360, "Pit1" },
        { 690, 340, "Pit2" },
        { 710, 360, "Pit3" },
        { 690, 380, "Back" },
        { 640, 360, "Center" },
    };

    // Ancient Tunnels
    Waypoint ancientTunnelsRoute[] = {
        { 640, 360, "Entrance" },
        { 660, 340, "TunnelN" },
        { 680, 360, "TunnelE" },
        { 670, 380, "TunnelS" },
        { 640, 370, "Center" },
        { 620, 350, "TunnelW" },
        { 640, 360, "Entrance2" },
    };

    // Mausoleum
    Waypoint mausoleumRoute[] = {
        { 640, 360, "Gate" },
        { 650, 340, "Upper" },
        { 670, 360, "Right" },
        { 650, 380, "Lower" },
        { 630, 360, "Left" },
        { 640, 360, "Center" },
    };

    // Leveling route (basic exploration)
    Waypoint levelingRoute[] = {
        { 640, 360, "Center" },
        { 670, 340, "NE" },
        { 700, 360, "E" },
        { 670, 380, "SE" },
        { 640, 400, "S" },
        { 610, 380, "SW" },
        { 580, 360, "W" },
        { 610, 340, "NW" },
    };

    Waypoint* currentRoute = nullptr;
    int routeLength = 0;

    if (_stricmp(route, "Cow Level") == 0)
    {
        currentRoute = cowLevelRoute;
        routeLength = sizeof(cowLevelRoute) / sizeof(Waypoint);
    }
    else if (_stricmp(route, "Pit") == 0)
    {
        currentRoute = pitRoute;
        routeLength = sizeof(pitRoute) / sizeof(Waypoint);
    }
    else if (_stricmp(route, "Ancient Tunnels") == 0)
    {
        currentRoute = ancientTunnelsRoute;
        routeLength = sizeof(ancientTunnelsRoute) / sizeof(Waypoint);
    }
    else if (_stricmp(route, "Mausoleum") == 0)
    {
        currentRoute = mausoleumRoute;
        routeLength = sizeof(mausoleumRoute) / sizeof(Waypoint);
    }
    else if (_stricmp(route, "Leveling") == 0)
    {
        currentRoute = levelingRoute;
        routeLength = sizeof(levelingRoute) / sizeof(Waypoint);
    }
    else
    {
        // Default to cow level
        currentRoute = cowLevelRoute;
        routeLength = sizeof(cowLevelRoute) / sizeof(Waypoint);
    }

    // Execute waypoint clicks continuously
    while (m_isRunning && currentRoute)
    {
        for (int i = 0; i < routeLength && m_isRunning; i++)
        {
            int x = currentRoute[i].x;
            int y = currentRoute[i].y;

            // Add some randomness to avoid detection
            int randX = (rand() % 20) - 10;  // ±10 pixels
            int randY = (rand() % 20) - 10;

            x += randX;
            y += randY;

            // Right-click at waypoint
            SetCursorPos(x, y);
            Sleep(50 + (rand() % 100));  // Variable delay
            mouse_event(MOUSEEVENTF_RIGHTDOWN, 0, 0, 0, 0);
            Sleep(30 + (rand() % 50));
            mouse_event(MOUSEEVENTF_RIGHTUP, 0, 0, 0, 0);
            Sleep(300 + (rand() % 400));  // Wait for character to move
        }
    }
}

