bool BotEngine::Initialize()
{
    if (m_isInitialized)
        return true;

    if (!FindGameProcess())
    {
        return false;
    }

    if (!AttachToProcess(m_processId))
    {
        return false;
    }

    // Set up keyboard hook for backtick toggle
    s_instance = this;
    if (!s_keyboardHook)
    {
        s_keyboardHook = SetWindowsHookEx(WH_KEYBOARD_LL, KeyboardHookProc, GetModuleHandleA(nullptr), 0);
    }

    m_isInitialized = true;
    return true;
}

